# generated by tools/ail2py.py from number_lines_core.ail; edit the .ail until onelang s16
def number_lines(content: str) -> str:
    result = ''
    number = 1
    for line in content.splitlines():
        result = result + str(number) + ': ' + line + '\n'
        number = number + 1
    return result
